{
  "round": 2,
  "streams": [
    {
      "id": "F1",
      "description": "Non-nominal, abstract, and propositional anaphora: resolution to proposition-, event-, situation-, clause-, or discourse-segment antecedents rather than only nominal entities."
    },
    {
      "id": "F2",
      "description": "Dialogue discourse attachment and response relations: prediction of the earlier discourse unit to which a contribution attaches, together with its discourse relation."
    },
    {
      "id": "F3",
      "description": "Question-answer attachment, answerhood, QUD, and unresolved questions: alignment of responses to prior questions or issues, including multi-question, partial, empty, and unresolved cases."
    },
    {
      "id": "F5",
      "description": "Workplace email and enterprise-dialogue response semantics: empirical response alignment in authentic organizational or comparable asynchronous communication."
    },
    {
      "id": "F6",
      "description": "Antecedent annotation and span-level response-target evaluation: annotation or evaluation linking a response or anaphor to exact antecedent spans or discourse units."
    },
    {
      "id": "F7",
      "description": "Composite, multiple, split, and discontinuous antecedents: representations permitting more than one antecedent unit or more complex-than-single-parent attachment."
    },
    {
      "id": "F8",
      "description": "Ambiguous, null, unsupported, and missing antecedents with abstention: representations that do not force every expression or response onto a single antecedent."
    },
    {
      "id": "F10",
      "description": "Conversation disentanglement and reply-to graph prediction: nonlocal attachment of conversational units in interleaved or asynchronous dialogue."
    }
  ],
  "decisions": [
    {
      "paper_id": "manual-a6314f615a",
      "decision": "ADMIT",
      "reason": "Directly studies sentence-level question-answer pairing in asynchronous email and predicts which earlier question a later answer addresses using thread, lexical, and contextual evidence. This is unusually close to gap-3 and supplies target-domain empirical evidence for non-adjacent email reply alignment. Identity is UNCHECKED, so bibliographic verification should occur during acquisition.",
      "stream_id": "F5",
      "role": "DIRECT",
      "confidence": 0.98
    },
    {
      "paper_id": "doi-10-1609-aaai-v33i01-3301134",
      "decision": "ADMIT",
      "reason": "The abstract explicitly models question-answer utterance alignment in multi-round conversations and allows empty as well as multiple alignments. That materially strengthens F3 and directly informs gap-3 and gap-5 because the model does not assume a forced one-to-one question-response mapping. Identity is UNCHECKED.",
      "stream_id": "F3",
      "role": "DIRECT",
      "confidence": 0.99
    },
    {
      "paper_id": "manual-a2970abe9c",
      "decision": "REJECT",
      "reason": "The capability is relevant, but this system paper appears to implement the same NTCIR-16 Question Answer Alignment task whose overview candidate separately defines the task, gold standard, and evaluation. The abstract does not show a distinctive capability concerning partial, multiple, null, ambiguous, or unresolved alignment that would justify an additional reading slot. Identity is also UNCHECKED."
    },
    {
      "paper_id": "doi-10-1109-icaicta63815-2024-10762999",
      "decision": "ADMIT",
      "reason": "Directly targets transcripts where several questions are asked together and answers are subsequently delivered one by one, with explicit segmentation and alignment of corresponding units. This is strong empirical evidence for competing prior questions and batch-to-unit correspondence, closely addressing gap-3. Identity is UNCHECKED.",
      "stream_id": "F3",
      "role": "DIRECT",
      "confidence": 0.98
    },
    {
      "paper_id": "doi-10-1007-978-3-540-70939-8-48",
      "decision": "REJECT",
      "reason": "The paper uses automatically detected email question-answer pairs as an input to summarization. Its evaluation concerns summary quality rather than validating reply-to-question scope itself, so it is indirect evidence and duplicates the more directly relevant email alignment candidates."
    },
    {
      "paper_id": "doi-10-1016-j-pragma-2007-07-011",
      "decision": "ADMIT",
      "reason": "Provides empirical analysis of turns containing multiple questions and examines how responses, missing rejoinders, repair, and problematic answers interact with that organization. Although not computational alignment and not workplace email, it materially strengthens the empirical understanding behind gap-3 by documenting why answer scope cannot safely be equated with adjacency.",
      "stream_id": "F3",
      "role": "DIRECT",
      "confidence": 0.9
    },
    {
      "paper_id": "doi-10-20736-0002002282",
      "decision": "REJECT",
      "reason": "Relevant question-answer alignment capability, but the abstract describes another system for the same NTCIR-16 assembly-minute task without a unique treatment of multiple, null, partial, or unresolved alignments. The task overview and stronger multi-question candidates cover the needed capability with less duplication."
    },
    {
      "paper_id": "doi-10-20736-0002002284",
      "decision": "PENDING",
      "reason": "The batch question-answer setting and assignment formulation could be useful for gap-3, but the abstract does not establish whether the Hungarian assignment forces a one-to-one complete matching or permits unmatched questions, unmatched answers, partial answers, or many-to-many mappings. Admit only if the full paper shows support for unresolved or non-bijective cases rather than merely optimizing forced batch pairing."
    },
    {
      "paper_id": "manual-5a32708675",
      "decision": "ADMIT",
      "reason": "Defines an independently evaluated Question Answer Alignment task with gold correspondences in collective-questioning settings where several questions and answers occur in batches. This materially strengthens F3 by providing task formulation and evaluation evidence rather than only another model implementation. It is particularly useful for gap-3. Identity is UNCHECKED.",
      "stream_id": "F3",
      "role": "DIRECT",
      "confidence": 0.97
    },
    {
      "paper_id": "doi-10-1016-j-ipm-2023-103613",
      "decision": "REJECT",
      "reason": "The abstract establishes generic discourse-relation extraction in argumentative multiparty dialogue, but it does not show a distinctive contribution on response scope, question resolution, explicit proposition targets, multiple antecedents, or abstention beyond capabilities already represented by more directly relevant dialogue-attachment papers."
    },
    {
      "paper_id": "doi-10-3233-aic-2012-0516",
      "decision": "ADMIT",
      "reason": "Direct email evidence that extends question-answer pairing beyond syntactic interrogatives to imperative and declarative request forms. This is materially important for workplace communication, where requests and propositions are often not phrased as questions, and complements rather than merely duplicates the earlier interrogative-oriented email alignment work.",
      "stream_id": "F5",
      "role": "DIRECT",
      "confidence": 0.99
    },
    {
      "paper_id": "manual-be69c3aa17",
      "decision": "ADMIT",
      "reason": "Presents an evaluated annotation scheme for abstract pronominal anaphora whose antecedents may be verb phrases, clauses, or larger discourse segments. The annotation and inter-coder evidence directly strengthen both non-nominal antecedent modeling and the span-level methodology needed for gap-2. Identity is UNCHECKED.",
      "stream_id": "F6",
      "role": "DIRECT",
      "confidence": 0.98
    },
    {
      "paper_id": "doi-10-18653-v1-2023-eacl-main-247",
      "decision": "ADMIT",
      "reason": "Predicts discourse attachment jointly with relation labels and explicitly permits a discourse node to have multiple parents. That property materially strengthens F7 because it provides an evaluated alternative to single-antecedent tree assumptions and is directly relevant to the still-open question of composite or multi-unit reply scope.",
      "stream_id": "F7",
      "role": "TRANSFER",
      "confidence": 0.97
    },
    {
      "paper_id": "manual-7743c50805",
      "decision": "ADMIT",
      "reason": "Reports annotation experiments in dialogue where annotators identify discourse-deictic antecedents as unconstrained regions of dialogue text and evaluates convergence on those regions. This directly supports exact span-level treatment of proposition-like and discourse-segment antecedents, making it especially relevant to gap-2. Identity is UNCHECKED.",
      "stream_id": "F6",
      "role": "DIRECT",
      "confidence": 0.99
    },
    {
      "paper_id": "doi-10-63317-53p2a7tyghmi",
      "decision": "REJECT",
      "reason": "Although it contains functional-dependence links and agreement/disagreement labels, the abstract's primary contribution is analysis of subjectivity in Reddit interactions. It does not show proposition-level target identification, exact response scope, or a distinctive attachment capability that materially strengthens F4 or F9 for this review."
    },
    {
      "paper_id": "doi-10-18653-v1-s15-1035",
      "decision": "ADMIT",
      "reason": "Explicitly separates detection of discourse-deictic pronouns from resolution to verbal or clausal antecedents and evaluates both stages. This materially strengthens F1 with computational evidence for selecting non-nominal, proposition-like antecedents rather than treating abstract reference as ordinary entity coreference.",
      "stream_id": "F1",
      "role": "DIRECT",
      "confidence": 0.97
    },
    {
      "paper_id": "manual-e4d6ad7ca1",
      "decision": "ADMIT",
      "reason": "The annotation representation permits multiple antecedents for ambiguous expressions and includes discourse antecedents denoting abstract entities such as events, actions, and plans. That combination directly strengthens F8 and supplies useful transfer evidence for gap-5 because ambiguity need not be collapsed into a forced single antecedent. Identity is UNCHECKED.",
      "stream_id": "F8",
      "role": "TRANSFER",
      "confidence": 0.96
    },
    {
      "paper_id": "manual-f6b3355bcf",
      "decision": "PENDING",
      "reason": "The corpus study clearly concerns clarification requests and intention-related problems, but the abstract does not establish that clarification acts are annotated against explicit antecedent propositions or spans. Admit under F4 only if the full paper exposes target-level annotation or evaluation rather than only classifying clarification-sequence types. Identity is UNCHECKED."
    },
    {
      "paper_id": "manual-1e515febba",
      "decision": "ADMIT",
      "reason": "Distinguishes individual, discourse-deictic, and vague uses before resolving discourse-deictic cases against preceding dialogue. This materially strengthens F1 and also informs F8 by separating vague/non-resolvable cases from genuine abstract-anaphoric resolution rather than forcing all demonstratives onto antecedents. Identity is UNCHECKED.",
      "stream_id": "F1",
      "role": "DIRECT",
      "confidence": 0.95
    },
    {
      "paper_id": "manual-2ce01eecee",
      "decision": "REJECT",
      "reason": "The abstract provides useful evidence that demonstratives may refer to plans or larger discourse material, but the core capability substantially overlaps the admitted abstract/discourse-deictic annotation and resolution papers. It does not show a unique span, ambiguity, multiple-antecedent, or response-scope contribution sufficient to justify another reading slot. Identity is UNCHECKED."
    },
    {
      "paper_id": "manual-14f72b0c0b",
      "decision": "ADMIT",
      "reason": "Introduces a corpus with full discourse structures and explicit links between elementary discourse units in interleaved multiparty chat. This materially strengthens F10 by supplying annotated nonlocal conversational attachment data that can transfer to asynchronous reply-to graph prediction. Identity is UNCHECKED.",
      "stream_id": "F10",
      "role": "TRANSFER",
      "confidence": 0.96
    },
    {
      "paper_id": "doi-10-3115-1117736-1117743",
      "decision": "REJECT",
      "reason": "The paper is directly about abstract anaphora in dialogue, but the abstract shows essentially the same broad capability as the admitted discourse-deictic resolution work without an additional annotation, multiple-antecedent, abstention, or response-scope contribution needed to close an open gap."
    },
    {
      "paper_id": "doi-10-1007-s10489-013-0481-1",
      "decision": "ADMIT",
      "reason": "Empirically distinguishes answered discussions from unresolved discussions and unanswered questions rather than assuming that every issue receives a response. Although the domain is student forums, this materially strengthens F3 as transfer evidence for the unresolved-question component of gap-3 and for preserving open work instead of closing it from weak evidence.",
      "stream_id": "F3",
      "role": "DIRECT",
      "confidence": 0.91
    },
    {
      "paper_id": "doi-10-18653-v1-d15-1109",
      "decision": "ADMIT",
      "reason": "Directly predicts which preceding elementary discourse unit a new unit attaches to and predicts the discourse relation in interleaved multiparty chat. This materially strengthens F2 with evaluated sub-message attachment and relation classification, the closest general dialogue analogue to response-to-proposition selection.",
      "stream_id": "F2",
      "role": "DIRECT",
      "confidence": 0.99
    },
    {
      "paper_id": "doi-10-1093-jos-17-1-51",
      "decision": "ADMIT",
      "reason": "The corpus analysis explicitly distinguishes nominal antecedents, sentential/discourse-deictic antecedents, and vague cases with no clearly identifiable linguistic antecedent. This directly strengthens F8 because it provides empirical motivation for null or unresolved outcomes instead of mandatory nearest-antecedent attachment, which is central to gap-5.",
      "stream_id": "F8",
      "role": "TRANSFER",
      "confidence": 0.97
    }
  ],
  "notes": "Admission was deliberately selective. The strongest additions are direct email question-answer alignment, multi-question and batch question-answer alignment, span-level abstract-antecedent annotation, explicit multi-parent discourse attachment, and empirical representations of vague or unresolved antecedents. No candidate abstract establishes direct proposition-level agreement, rejection, or approval scope in authentic workplace email, so gap-1 remains open. The admitted annotation papers materially inform gap-2 but do not by themselves validate the complete msgloom target scheme covering exact, partial, ambiguous, unsupported, discontinuous, and multiple response targets. Gap-4 gains transfer evidence from multi-parent discourse attachment but still lacks direct multi-proposition workplace reply-scope evaluation. Gap-5 gains evidence that vague, ambiguous, and unresolved antecedents should be representable, but no candidate validates the product-specific cost model for over-broad links versus abstention."
}
